SELECT FROM sys_datasource
del_flag = '0' AND ds_name LIKE CONCAT('%', #{dsName}, '%') AND db_type = #{dbType} AND remark = #{remark}
ORDER BY create_time DESC

mapper.update:
UPDATE sys_datasource
ds_name = #{dsName}, db_type = #{dbType}, jdbc_url = #{jdbcUrl}, driver_class_name = #{driverClassName}, host = #{host}, port = #{port}, database_name = #{databaseName}, username = #{username}, password = #{password}, connect_params = #{connectParams}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
WHERE id = #{id}
